// CommuLingo guided reading (format 'guided-reading', 2026-10-24): each lesson
// shows a passage of the site's full translation first, then one question on
// it. Korean passages are verbatim from the document marx-eighteenth-brumaire
// (scripts/check-course-source-excerpts.js checks them and their anchors).
// Marx and Engels wrote these texts in German, so the English passages are
// translated here from the German text the document carries. A passage may
// skip text with ' … '.

function t(ko, en) {
    return { ko, en };
}

const DOC = '/commulingo/docs/marx-eighteenth-brumaire';
const BOOK = 'marx-eighteenth-brumaire';
const FROM_GERMAN = ' (our translation from the German)';

const LABELS = {
    'preface-1869': t('마르크스, 제2판 서문 (1869)', 'Marx, preface to the second edition (1869)' + FROM_GERMAN),
    'preface-1885': t('엥겔스, 제3판 서문 (1885)', 'Engels, preface to the third edition (1885)' + FROM_GERMAN),
    ch1: t('『브뤼메르 18일』 I장', 'The Eighteenth Brumaire, chapter I' + FROM_GERMAN),
    ch2: t('『브뤼메르 18일』 II장', 'The Eighteenth Brumaire, chapter II' + FROM_GERMAN),
    ch3: t('『브뤼메르 18일』 III장', 'The Eighteenth Brumaire, chapter III' + FROM_GERMAN),
    ch4: t('『브뤼메르 18일』 IV장', 'The Eighteenth Brumaire, chapter IV' + FROM_GERMAN),
    ch5: t('『브뤼메르 18일』 V장', 'The Eighteenth Brumaire, chapter V' + FROM_GERMAN),
    ch6: t('『브뤼메르 18일』 VI장', 'The Eighteenth Brumaire, chapter VI' + FROM_GERMAN),
    ch7: t('『브뤼메르 18일』 VII장', 'The Eighteenth Brumaire, chapter VII' + FROM_GERMAN),
};

function passage(anchor, contextKo, contextEn, quoteKo, quoteEn) {
    return {
        context: t(contextKo, contextEn),
        source: { href: `${DOC}#${anchor}`, label: LABELS[anchor], quote: t(quoteKo, quoteEn) },
    };
}

// Choices and their feedback are authored correct answer first, which is how
// they are stored (answer 0); the player shuffles them for display.
function q(where, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback) {
    return {
        type: 'multiple_choice',
        points: 0,
        context: where.context,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: koChoices, en: enChoices },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
        choiceFeedback: { ko: koFeedback, en: enFeedback },
        source: where.source,
    };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, questions) {
    const id = `${BOOK}-ch${String(ch).padStart(2, '0')}`;
    return {
        id,
        volumeNumber: -1,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        lessons: [{
            id: `${id}-basic`,
            level: 'basic',
            title: t(titleKo, titleEn),
            questions: questions.map((item, index) => ({ ...item, id: item.id || `q${index + 1}`, points: 2 })),
        }],
    };
}

